captured graph and time the kernels.  That is not enough here: the elastic gather
and the PLE lookup run OUTSIDE the graph, and the gather's host-to-device copy is
the one part that cannot be measured from the graph at all.  This tool therefore
reports three things:

  1. the kernels inside the decode graph, by class
  2. the elastic gather, measured live (it runs outside the"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=1))
        print(f"  saved {path}")
    elif cmd == "check":
        name = sys.argv[2]
        reference = json.loads((D / f"{name}.json").read_text())
        current = collect(cached=reference)
        print_report(f"{name} vs current", stats(reference, current))
    elif cmd == "compare":
        a, b = sys.argv[2], sys.argv[3]
        ra = json.loads((D / f"{a}.json").read_text())
        rb = json.loads((D / f"{b}.json").read_text())
        print_report(f"{b} vs {a}", stats(ra, rb))
    else:
        print(f"  unknown command {cmd}")
        sys.exit(1)


if __name__ == "__main__":
    main()


